import{c as e,Q as s,j as t,m as l}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Follow","description":"","frontmatter":{},"headers":[{"level":1,"title":"Follow","slug":"follow"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpParamDef/Follow.md","filePath":"api/Utils-API/原型注册与管理/OpParamDef/Follow.md"}'),p={name:"api/Utils-API/原型注册与管理/OpParamDef/Follow.md"};function n(o,a,i,r,h,d){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="follow" tabindex="-1">Follow <a class="header-anchor" href="#follow" aria-label="Permalink to &quot;Follow&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于指定当前输入/输出的datatype/format/shape信息与之前定义过的某个输入一致。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>datatype/format/shape全部信息保持一致</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;Follow(const char *paramName)</span></span></code></pre></div></li><li><p>datatype/format/shape指定信息保持一致</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;Follow(const char *paramName, FollowType ftype)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>paramName</td><td>输入</td><td>之前定义过的输入名。</td></tr><tr><td>ftype</td><td>输入</td><td>ftype类型为枚举类FollowType，表示Follow的模式，取值如下： ALL，datatype/format/shape与paramName均保持一致；DTYPE，datatype与paramName保持一致；FORMAT，format与paramName保持一致；SHAPE，shape与paramName保持一致。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="./OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>所有Follow的数据源头仅支持为Input。</li><li>针对shape推导，仅支持输出参数Follow输入参数，不支持输入参数Follow另一个输入参数。</li><li>可以支持链式Follow，例如C Follow B，B Follow A，但此时Follow的模式不可中途变更（ftype需要保持一致）。</li><li>使用Follow接口通常比InferShape函数逻辑更加简单，能用Follow表达的逻辑，建议使用Follow接口，则无需再编写注册InferShape函数。</li><li>InferShape推导函数和使用Follow接口去Follow shape不能混用，即不支持部分输出采用Infershape推导、部分输出采用Follow推导的情况。若用户同时使用了InferShape函数和Follow接口，以用户的InferShape函数为准，需要保证在InferShape函数中能够推导出所有的输出shape。</li><li>datatype/format同时支持Follow输入的参数类型为<a href="./DataTypeList.html">DataTypeList</a>/<a href="./FormatList.html">FormatList</a> ，调用Follow后，当前输入/输出的datatype/format与paramName组合后的datatype/format一致。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>输出“y1”Follow输入“x1”场景，此时“y1”的datatype、format以及shape都将会和“x1”保持一致。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this-&gt;Input(&quot;x1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>this-&gt;Input(&quot;x2&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>this-&gt;Output(&quot;y1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .Follow(&quot;x1&quot;);</span></span></code></pre></div></li><li><p>链式follow场景，y1 -&gt; x2 -&gt; x1。此时“y1”的datatype、format以及shape都将会和“x1”保持一致，“x2”的datatype、format和“x1”保持一致。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this-&gt;Input(&quot;x1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>this-&gt;Input(&quot;x2&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .Follow(&quot;x1&quot;);</span></span>
<span class="line"><span>this-&gt;Output(&quot;y1&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .Follow(&quot;x2&quot;);</span></span></code></pre></div></li></ul>`,13)])])}const m=e(p,[["render",n]]);export{u as __pageData,m as default};
